  keyTerms: [
    { term: "تائو (道)", definition: "راه؛ خاستگاه و الگویِ وصف‌ناپذیر و خودانگیختهٔ همهٔ هستی. مفهومِ مرکزیِ آیین تائو، تائو هم متعالی است (فراسویِ جهانِ تجلی‌یافته) و هم درون‌ماندگار (نفوذکننده در همهٔ چیزها)." },
    { term: "دِه (德)", definition: "فضیلت، قدرت یا کارآیی؛ تجلیِ خاصِ تائو در موجودات و چیزهای فردی. در دائودِه‌جینگ، دِه فضیلتِ اخلاقی نیست بلکه توانایی و انسجامِ طبیعی است." },
    { term: "ووِی (無為)", definition: "بی‌کنشی یا کنشِ بی‌زحمت؛ عمل در همسازی با فرایندهای طبیعی بی‌آنکه بزوری، تلاشی یا تحمیلِ سازه‌های مصنوعی. ووِی شیوهٔ آرمانیِ رفتار برایِ دائوییان است." },
    { term: "زیران (自然)", definition: "طبیعی‌بودن یا خودانگیختگی؛ کیفیتِ «خودچنین» یا «آن‌گونه که خود هست». زیران شیوهٔ خودانگیخته و بی‌غرضِ کنشِ تائو و آرمانِ رفتارِ انسانی را توصیف می‌کند." },
    { term: "یین-یانگ (陰陽)", definition: "نیروهای قطبیِ مکمل و وابسته به هم: یین (تاریکی، پذیرندگی، زنانگی، زمین) و یانگ (روشنایی، فعالیت، مردانگی، آسمان). توازنِ پویایشان برایِ همسازی و سلامت ضروری است." },
    { term: "چی (氣)", definition: "نفسِ حیاتی یا انرژی؛ نیروی جان‌بخشی که در بدن و در سراسرِ کیهان جریان دارد. چی باید پرورانده و گردانده شود تا سلامت و نیرومندیِ معنوی حفظ شود." },
    { term: "جینگ (精)", definition: "جوهر؛ مادهٔ حیاتیِ بنیادین پیوسته با توانِ باروری و نیرومندیِ جسمانی. جینگ متناهی است و باید در خودپروریِ دائویی نگاه داشته و پالوده شود." },
    { term: "شن (神)", definition: "روان یا آگاهی؛ جنبهٔ پالوده و درخشانِ خود. شن باید از راهِ مراقبه ثابت و پرورانده شود تا به تحققِ معنوی انجامد." },
    { term: "نِی‌دان (內丹)", definition: "کیمیاگریِ درونی؛ تمرینِ پالایشِ جینگ به چی، چی به شن و شن به تهی یا تائو، برایِ پرورشِ «جنینِ جاودان» در درونِ بدن." },
    { term: "شیان (仙)", definition: "جاودان؛ موجودی که از راهِ خودپروری، مراقبه و کیمیاگریِ دائویی از مرگِ متعارف فراتر رفته و از نیروهای فراطبیعی و طول‌عمر برخوردار است." },
    { term: "سانچینگ (三清)", definition: "سه ناب؛ سه‌گانهٔ برترِ خدایانِ دائویی: یوان‌شی تیان‌زون (ونرابلِ آسمانیِ آغازِ نخستین)، لینگ‌بائو تیان‌زون و دائودِه تیان‌زون (لائوتزوی الوهیت‌یافته)." },
    { term: "جیائو (醮)", definition: "مناسکِ بازآفرینیِ کیهانی و هدیه؛ آیین‌های چندروزهٔ دائویی شاملِ رژه، موسیقی، خواندنِ متونِ مقدس و درخواستِ برکت و رستگاری." },
    { term: "ژای (齋)", definition: "آیین‌های پاکسازی و خلوت؛ مراسمِ دائویی شاملِ روزه، توبه و خواندنِ متونِ مقدس برای پاک‌کردنِ شرکت‌کنندگان و کفارهٔ گناهان." },
    { term: "فو (符)", definition: "طلسم؛ نمادی نوشته یا کشیده‌شده که با نیرویِ معنوی آکنده شده و برایِ حمایت، شفا و ارتباط با امرِ الهی به کار می‌رود. طلسم‌ها ممکن است سوزانده، خورده یا پوشیده شوند." },
    { term: "یانگ‌شنگ (養生)", definition: "پرورشِ زندگی؛ طیفِ گسترده‌ای از تمرین‌های سلامت و طول‌عمر شاملِ رژیمِ غذایی، تمرینِ نفس، تمرینِ بدنی و فنونِ جنسی." },
    { term: "تای‌جی‌چوان (太極拳)", definition: "مشتِ برترین قطب؛ هنرِ رزمی و تمرینِ مراقبه‌ای تأکیدکننده بر حرکاتِ آهسته و روان، پرورشِ انرژیِ درونی و توازنِ یین و یانگ." },
    { term: "دائوزانگ (道藏)", definition: "کانونِ دائویی؛ مجموعهٔ جامعِ متونِ مقدسِ دائویی تدوین‌شده در طولِ سده‌ها که در سلسلهٔ مینگ (۱۴۴۵ میلادی) صورتِ نهایی یافت و بیش از ۵٬۰۰۰ جلد دارد." },
    { term: "تیانشی (天師)", definition: "استادِ آسمانی؛ لقبِ موروثیِ رهبرِ سنتِ ژنگ‌یی (وحدتِ راستین)، منسوب به ژانگ داولینگ، بنیان‌گذارِ جنبشِ استادانِ آسمانی (۱۴۲ میلادی)." },
    { term: "کوان‌جن (全真)", definition: "کمالِ تمام‌عیار؛ سنتِ راهبانهٔ دائویی، بنیان‌گذاری‌شده به دستِ وانگ چونگ‌یانگ (۱۱۱۳–۱۱۷۰ میلادی)، تأکیدکننده بر تجرد، مراقبه، کیمیاگریِ درونی و رفتارِ اخلاقی." },
    { term: "ژنگ‌یی (正一)", definition: "وحدتِ راستین؛ سنتِ دائویی برخاسته از استادانِ آسمانی که روحانیتی متأهل را حفظ می‌کند و بر آیین‌های جمعی، مناسک و اخراجِ ارواح تمرکز دارد." }
  ],

